public class Solution {
    public String makePalindrome(String string) {
        if (string == null || string.length() <= 1) {
            return string;
        }

        int n = string.length();
        String rev = new StringBuilder(string).reverse().toString();

        int[] combined = new int[2 * n + 1];
        for (int i = 0; i < n; i++) {
            combined[i] = rev.charAt(i);
        }
        combined[n] = -1;
        for (int i = 0; i < n; i++) {
            combined[n + 1 + i] = string.charAt(i);
        }

        int[] pi = new int[combined.length];
        for (int i = 1; i < combined.length; i++) {
            int j = pi[i - 1];
            while (j > 0 && combined[i] != combined[j]) {
                j = pi[j - 1];
            }
            if (combined[i] == combined[j]) {
                j++;
            }
            pi[i] = j;
        }

        int k = pi[combined.length - 1];
        String prefix = string.substring(0, n - k);

        StringBuilder result = new StringBuilder(string);
        result.append(new StringBuilder(prefix).reverse());
        return result.toString();
    }
}
