public class Solution {
    public List<Integer> parseMusic(String string) {
        List<Integer> beats = new ArrayList<>();
        if (string == null || string.trim().isEmpty()) {
            return beats;
        }

        String[] notes = string.trim().split("\\s+");
        for (String note : notes) {
            switch (note) {
                case "o":
                    beats.add(4);
                    break;
                case "o|":
                    beats.add(2);
                    break;
                case ".|":
                    beats.add(1);
                    break;
                default:
                    break;
            }
        }

        return beats;
    }
}
