import java.util.List;

public class Solution {
    public double findZero(List<Double> xs) {
        if (xs.get(0) == 0.0) return 0.0;

        double M = 1.0;
        double fNeg = eval(xs, -M);
        double fPos = eval(xs, M);

        while (sign(fNeg) == sign(fPos)) {
            M *= 2.0;
            if (M == Double.POSITIVE_INFINITY) {
                M = Double.MAX_VALUE;
                fNeg = eval(xs, -M);
                fPos = eval(xs, M);
                break;
            }
            fNeg = eval(xs, -M);
            fPos = eval(xs, M);
        }

        if (fNeg == 0.0) return -M;
        if (fPos == 0.0) return M;

        double a = -M;
        double b = M;
        double fa = fNeg;
        double fb = fPos;

        for (int i = 0; i < 2000; i++) {
            double mid = a / 2.0 + b / 2.0;
            double fm = eval(xs, mid);
            if (fm == 0.0) return mid;
            if (sign(fm) == sign(fa)) {
                a = mid;
                fa = fm;
            } else {
                b = mid;
                fb = fm;
            }
        }

        return a / 2.0 + b / 2.0;
    }

    private double eval(List<Double> xs, double x) {
        double result = 0.0;
        for (int i = xs.size() - 1; i >= 0; i--) {
            result = result * x + xs.get(i);
        }
        return result;
    }

    private int sign(double v) {
        if (v > 0.0) return 1;
        if (v < 0.0) return -1;
        return 0;
    }
}
