public class Solution {
    public int fizzBuzz(int n) {
        if (n <= 0) return 0;
        return (int) countUpTo(n - 1);
    }

    private long countUpTo(int limit) {
        if (limit < 0) return 0;

        String s = Integer.toString(limit);
        int len = s.length();

        long[][][][] dp = new long[2][11][13][2];
        dp[1][0][0][0] = 1;

        for (int pos = 0; pos < len; pos++) {
            int limitDigit = s.charAt(pos) - '0';
            long[][][][] next = new long[2][11][13][2];

            for (int tight = 0; tight < 2; tight++) {
                for (int m11 = 0; m11 < 11; m11++) {
                    for (int m13 = 0; m13 < 13; m13++) {
                        long count = dp[tight][m11][m13][0];
                        long occ = dp[tight][m11][m13][1];
                        if (count == 0 && occ == 0) continue;

                        int maxDigit = (tight == 1) ? limitDigit : 9;
                        for (int d = 0; d <= maxDigit; d++) {
                            int ntight = (tight == 1 && d == limitDigit) ? 1 : 0;
                            int nm11 = (m11 * 10 + d) % 11;
                            int nm13 = (m13 * 10 + d) % 13;

                            next[ntight][nm11][nm13][0] += count;
                            next[ntight][nm11][nm13][1] += occ + (d == 7 ? count : 0);
                        }
                    }
                }
            }
            dp = next;
        }

        long total = 0;
        for (int tight = 0; tight < 2; tight++) {
            for (int m11 = 0; m11 < 11; m11++) {
                for (int m13 = 0; m13 < 13; m13++) {
                    if (m11 == 0 || m13 == 0) {
                        total += dp[tight][m11][m13][1];
                    }
                }
            }
        }
        return total;
    }
}
