class Solution {
    public String decodeCyclic(String s) {
        StringBuilder sb = new StringBuilder(s.length());

        for (int i = 0; i < s.length(); i += 3) {
            int end = Math.min(i + 3, s.length());

            if (end - i == 3) {
                sb.append(s.charAt(i + 2));
                sb.append(s.charAt(i));
                sb.append(s.charAt(i + 1));
            } else {
                sb.append(s, i, end);
            }
        }

        return sb.toString();
    }
}
