class Solution {
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        long a = 0, b = 1;

        while (true) {
            long p = a + b;

            if (isPrime(p)) {
                n--;
                if (n == 0) {
                    return (int) p;
                }
            }

            a = b;
            b = p;
        }
    }

    private boolean isPrime(long x) {
        if (x < 2) {
            return false;
        }
        if (x == 2) {
            return true;
        }
        if (x % 2 == 0) {
            return false;
        }

        for (long i = 3; i <= x / i; i += 2) {
            if (x % i == 0) {
                return false;
            }
        }

        return true;
    }
}
