    public int fib4(int n) {
        if (n < 4) {
            return n == 2 ? 2 : 0;
        }

        int a = 0; // fib4(0)
        int b = 0; // fib4(1)
        int c = 2; // fib4(2)
        int d = 0; // fib4(3)

        for (int i = 4; i <= n; i++) {
            int next = a + b + c + d;
            a = b;
            b = c;
            c = d;
            d = next;
        }

        return d;
    }
}
