class Solution {
    public String changeBase(int x, int base) {
        if (x == 0) {
            return "0";
        }

        StringBuilder ret = new StringBuilder();
        long n = x;
        String sign = "";

        if (n < 0) {
            sign = "-";
            n = -n;
        }

        while (n > 0) {
            ret.append(n % base);
            n /= base;
        }

        return sign + ret.reverse().toString();
    }
}
