class Solution {
    public int modp(int n, int p) {
        long result = 1 % p;
        long base = 2 % p;
        int exp = n;

        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % p;
            }
            base = (base * base) % p;
            exp >>= 1;
        }

        return (int) result;
    }
}
