class Solution {
    public List<Integer> sortEven(List<Integer> l) {
        List<Integer> result = new ArrayList<>(l);
        List<Integer> even = new ArrayList<>();

        for (int i = 0; i < l.size(); i += 2) {
            even.add(l.get(i));
