public class Solution {
    public String circularShift(int x, int shift) {
        String sign = "";
        long value = x;
        if (value < 0) {
            sign = "-";
            value = -value;
        }

        String digits = Long.toString(value);
        int n = digits.length();

        if (shift > n) {
            return sign + new StringBuilder(digits).reverse().toString();
        }

        shift = shift % n;
        if (shift == 0) {
            return sign + digits;
        }

        String result = digits.substring(n - shift) + digits.substring(0, n - shift);
        return sign + result;
    }
}
