import java.util.*;

class Solution {
    public List<Integer> pluck(List<Integer> arr) {
        List<Integer> result = new ArrayList<>();
        if (arr == null || arr.isEmpty()) {
            return result;
        }

        int min = Integer.MAX_VALUE;
        int minIndex = -1;

        for (int i = 0; i < arr.size(); i++) {
            int value = arr.get(i);
            if (value % 2 == 0 && value < min) {
                min = value;
                minIndex = i;
            }
        }

        if (minIndex != -1) {
            result.add(min);
            result.add(minIndex);
        }

        return result;
    }
}
