import java.util.*;

class Solution {
    public List<Integer> strangeSortList(List<Integer> lst) {
        List<Integer> sorted = new ArrayList<>(lst);
        Collections.sort(sorted);

        List<Integer> res = new ArrayList<>(sorted.size());
        int left = 0;
        int right = sorted.size() - 1;
        boolean takeMin = true;

        while (left <= right) {
            if (takeMin) {
                res.add(sorted.get(left++));
            } else {
                res.add(sorted.get(right--));
            }
            takeMin = !takeMin;
        }

        return res;
    }
}
