import java.util.*;

class Solution {
    public boolean willItFly(List<Integer> q, int w) {
        long sum = 0;
        for (Integer x : q) {
            sum += x;
        }

        if (sum > w) {
            return false;
        }

        int i = 0;
        int j = q.size() - 1;

        while (i < j) {
            if (!Objects.equals(q.get(i), q.get(j))) {
                return false;
            }
            i++;
            j--;
        }

        return true;
    }
}
