class Solution {
    public boolean isMultiplyPrime(int a) {
        if (a < 8) {
            return false;
        }

        for (int i = 2; i <= a; i++) {
            if (!isPrime(i)) {
                continue;
            }
            for (int j = i; j <= a; j++) {
                if (!isPrime(j)) {
                    continue;
                }
                for (int k = j; k <= a; k++) {
                    if (!isPrime(k)) {
                        continue;
                    }
                    if (i * j * k == a) {
                        return true;
                    }
                    if (i * j * k > a) {
                        break;
                    }
                }
            }
        }

        return false;
    }

    private boolean isPrime(int n) {
        if (n < 2) {
            return false;
        }
        for (int d = 2; d * d <= n; d++) {
            if (n % d == 0) {
                return false;
            }
        }
        return true;
    }
}
