class Solution {
    public boolean iscube(int a) {
        long target = a < 0 ? -(long) a : (long) a;
        long lo = 0;
        long hi = 1291;

        while (lo <= hi) {
            long mid = (lo + hi) / 2;
            long cube = mid * mid * mid;

            if (cube == target) {
                return true;
            } else if (cube < target) {
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }

        return false;
    }
}
