class Solution {
    public boolean isSimplePower(int x, int n) {
        if (x == 0) {
            return n == 0;
        }
        if (n == 0) {
            return false;
        }
        if (n == 1) {
            return x == 1;
        }
        if (n == -1) {
            return x == 1 || x == -1;
        }
        if (x == 1) {
            return true;
        }

        long target = x;
        long base = n;
        long power = 1;

        while (true) {
            if (power == target) {
                return true;
            }
            if (Math.abs(power) > Math.abs(target)) {
                return false;
            }
            power *= base;
        }
    }
}
