class Solution {
    public boolean willItFly(List<Integer> q, int w) {
        int n = q.size();
        long sum = 0;

        for (int i = 0; i < n; i++) {
            sum += q.get(i);
            if (!q.get(i).equals(q.get(n - 1 - i))) {
                return false;
            }
        }

        return sum <= w;
    }
}
