import java.util.*;

public class Solution {
    public List<List<Integer>> getRow(List<List<Integer>> lst, int x) {
        List<List<Integer>> result = new ArrayList<>();
        if (lst == null) {
            return result;
        }

        for (int r = 0; r < lst.size(); r++) {
            List<Integer> row = lst.get(r);
            if (row == null) {
                continue;
            }

            for (int c = row.size() - 1; c >= 0; c--) {
                if (row.get(c) != null && row.get(c) == x) {
                    List<Integer> coordinate = new ArrayList<>(2);
                    coordinate.add(r);
                    coordinate.add(c);
                    result.add(coordinate);
                }
            }
        }

        return result;
    }
}
