import java.util.Arrays;

public class Solution {
    public String antiShuffle(String s) {
        if (s == null) {
            return null;
        }

        StringBuilder result = new StringBuilder();
        int i = 0;
        int n = s.length();

        while (i < n) {
            if (s.charAt(i) == ' ') {
                result.append(' ');
                i++;
            } else {
                int start = i;
                while (i < n && s.charAt(i) != ' ') {
                    i++;
                }

                char[] chars = s.substring(start, i).toCharArray();
                Arrays.sort(chars);
                result.append(chars);
            }
        }

        return result.toString();
    }
}
