class Solution {
    public String encode(String message) {
        StringBuilder sb = new StringBuilder();
        for (char c : message.toCharArray()) {
            if (Character.isLetter(c)) {
                char swapped = Character.isUpperCase(c)
                        ? Character.toLowerCase(c)
                        : Character.toUpperCase(c);

                char lower = Character.toLowerCase(swapped);
                if (lower == 'a' || lower == 'e' || lower == 'i' || lower == 'o' || lower == 'u') {
                    char base = Character.isUpperCase(swapped) ? 'A' : 'a';
                    swapped = (char) (base + ((lower - 'a' + 2) % 26));
                }

                sb.append(swapped);
            } else {
                sb.append(c);
            }
        }
        return sb.toString();
    }
}
