import java.math.BigDecimal;
import java.math.BigInteger;

public class Solution {
    public boolean anyInt(Object x, Object y, Object z) {
        if (!(x instanceof Number) || !(y instanceof Number) || !(z instanceof Number)) {
            return false;
        }
        Number nx = (Number) x;
        Number ny = (Number) y;
        Number nz = (Number) z;
        if (!isInteger(nx) || !isInteger(ny) || !isInteger(nz)) {
            return false;
        }
        BigDecimal bx = toBigDecimal(nx);
        BigDecimal by = toBigDecimal(ny);
        BigDecimal bz = toBigDecimal(nz);
        return bx.add(by).compareTo(bz) == 0 ||
               bx.add(bz).compareTo(by) == 0 ||
               by.add(bz).compareTo(bx) == 0;
    }

    private boolean isInteger(Number n) {
        if (n instanceof Integer || n instanceof Long || n instanceof Short || n instanceof Byte || n instanceof BigInteger) {
            return true;
        }
        if (n instanceof BigDecimal) {
            BigDecimal bd = (BigDecimal) n;
            return bd.stripTrailingZeros().scale() <= 0;
        }
        double d = n.doubleValue();
        return !Double.isNaN(d) && !Double.isInfinite(d) && d == Math.floor(d);
    }

    private BigDecimal toBigDecimal(Number n) {
        if (n instanceof BigDecimal) {
            return (BigDecimal) n;
        }
        if (n instanceof BigInteger) {
            return new BigDecimal((BigInteger) n);
        }
        if (n instanceof Integer || n instanceof Long || n instanceof Short || n instanceof Byte) {
            return BigDecimal.valueOf(n.longValue());
        }
        return BigDecimal.valueOf(n.doubleValue());
    }
}
