public class Solution {
    public String encode(String message) {
        StringBuilder result = new StringBuilder();

        for (int i = 0; i < message.length(); i++) {
            char c = message.charAt(i);

            if (Character.isLetter(c)) {
                char swapped = Character.isUpperCase(c)
                        ? Character.toLowerCase(c)
                        : Character.toUpperCase(c);

                char lower = Character.toLowerCase(swapped);

                if (lower == 'a' || lower == 'e' || lower == 'i' || lower == 'o' || lower == 'u') {
                    char shifted = (char) (lower + 2);
                    if (Character.isUpperCase(swapped)) {
                        shifted = Character.toUpperCase(shifted);
                    } else {
                        shifted = Character.toLowerCase(shifted);
                    }
                    result.append(shifted);
                } else {
                    result.append(swapped);
                }
            } else {
                result.append(c);
            }
        }

        return result.toString();
    }
}
