import java.util.*;

class Solution {
    public List<Integer> uniqueDigits(List<Integer> x) {
        List<Integer> result = new ArrayList<>();

        for (int n : x) {
            boolean hasOnlyOddDigits = true;
            int value = n;

            while (value > 0) {
                int digit = value % 10;
                if (digit % 2 == 0) {
                    hasOnlyOddDigits = false;
                    break;
                }
                value /= 10;
            }

            if (hasOnlyOddDigits) {
                result.add(n);
            }
        }

        Collections.sort(result);
        return result;
    }
}
