import java.util.*;

class Solution {
    public int countNums(List<Integer> arr) {
        int count = 0;
        for (int n : arr) {
            String s = Integer.toString(n);
            int sum = 0;
            int start = 0;
            int sign = 1;

            if (s.charAt(0) == '-') {
                sign = -1;
                start = 1;
            }

            for (int i = start; i < s.length(); i++) {
                int digit = s.charAt(i) - '0';
                if (i == start) {
                    digit *= sign;
                }
                sum += digit;
            }

            if (sum > 0) {
                count++;
            }
        }
        return count;
    }
}
