            int sum = 0;

            if (n < 0) {
                n = -n;

                int absSum = 0;
                long temp = n;
                while (temp > 0) {
                    absSum += temp % 10;
                    temp /= 10;
                }

                long firstDigit = n;
                while (firstDigit >= 10) {
                    firstDigit /= 10;
                }

                sum = absSum - 2 * (int) firstDigit;
