import java.util.*;

class Solution {
    public boolean moveOneBall(List<Integer> arr) {
        if (arr.size() == 0) {
            return true;
        }

        List<Integer> sortedArr = new ArrayList<>(arr);
        Collections.sort(sortedArr);

        int minValue = Collections.min(arr);
        int minIndex = arr.indexOf(minValue);

        List<Integer> rotatedArr = new ArrayList<>(arr.subList(minIndex, arr.size()));
        rotatedArr.addAll(arr.subList(0, minIndex));

        for (int i = 0; i < arr.size(); i++) {
            if (!rotatedArr.get(i).equals(sortedArr.get(i))) {
                return false;
            }
        }

        return true;
    }
}
