import java.util.List;

class Solution {
    public boolean moveOneBall(List<Integer> arr) {
        if (arr == null || arr.isEmpty()) {
            return true;
        }

        int n = arr.size();
        int drops = 0;

        for (int i = 0; i < n - 1; i++) {
            if (arr.get(i) > arr.get(i + 1)) {
                drops++;
            }
        }

        if (drops == 0) {
            return true;
        }

        if (drops > 1) {
            return false;
        }

        return arr.get(n - 1) < arr.get(0);
    }
}
