        for (String word : trimmed.split("\\s+")) {
            int consonants = 0;
            for (char c : word.toCharArray()) {
                char lower = Character.toLowerCase(c);
                if (lower >= 'a' && lower <= 'z' && "aeiou".indexOf(lower) == -1) {
                    consonants++;
                }
            }
            if (consonants == n) {
                result.add(word);
            }
        }

        return result;
    }
}
