import java.util.*;

class Solution {
    public String matchParens(List<String> lst) {
        String a = lst.get(0);
        String b = lst.get(1);

        if (isGood(a + b) || isGood(b + a)) {
            return "Yes";
        }
        return "No";
    }

    private boolean isGood(String s) {
        int balance = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '(') {
                balance++;
            } else {
                balance--;
            }
            if (balance < 0) {
                return false;
            }
        }
        return balance == 0;
    }
}
