class Solution {
    public List<Integer> getOddCollatz(int n) {
        List<Integer> oddCollatz = new ArrayList<>();

        if (n % 2 == 1) {
            oddCollatz.add(n);
        }

        while (n > 1) {
            if (n % 2 == 0) {
                n = n / 2;
            } else {
                n = 3 * n + 1;
            }

            if (n % 2 == 1) {
                oddCollatz.add(n);
            }
        }

        Collections.sort(oddCollatz);
        return oddCollatz;
    }
