class Solution {
    public boolean validDate(String date) {
        if (date == null) {
            return false;
        }
        date = date.strip();
        if (date.isEmpty()) {
            return false;
        }

        String[] parts = date.split("-", -1);
        if (parts.length != 3) {
            return false;
        }

        for (String part : parts) {
            if (part.isEmpty()) {
                return false;
            }
            for (int i = 0; i < part.length(); i++) {
                char c = part.charAt(i);
                if (c < '0' || c > '9') {
                    return false;
                }
            }
        }

        if (parts[0].length() > 2 || parts[1].length() > 2 || parts[2].length() != 4) {
            return false;
        }

        int month = Integer.parseInt(parts[0]);
        int day = Integer.parseInt(parts[1]);

        if (month < 1 || month > 12) {
            return false;
        }
        if (day < 1) {
            return false;
        }

        switch (month) {
            case 2:
                return day <= 29;
            case 4:
            case 6:
            case 9:
            case 11:
                return day <= 30;
            default:
                return day <= 31;
        }
    }
}
