public class Solution {
    public boolean validDate(String date) {
        if (date == null || date.isEmpty()) {
            return false;
        }

        if (date.length() != 10) {
            return false;
        }

        if (date.charAt(2) != '-' || date.charAt(5) != '-') {
            return false;
        }

        for (int i = 0; i < date.length(); i++) {
            if (i == 2 || i == 5) {
                continue;
            }
            char c = date.charAt(i);
            if (c < '0' || c > '9') {
                return false;
            }
        }

        int month = Integer.parseInt(date.substring(0, 2));
        int day = Integer.parseInt(date.substring(3, 5));

        if (month < 1 || month > 12) {
            return false;
        }

        if (day < 1) {
            return false;
        }

        int maxDay;
        switch (month) {
            case 1:
            case 3:
            case 5:
            case 7:
            case 8:
            case 10:
            case 12:
                maxDay = 31;
                break;
            case 4:
            case 6:
            case 9:
            case 11:
                maxDay = 30;
                break;
            case 2:
                maxDay = 29;
                break;
            default:
                return false;
        }

        return day <= maxDay;
    }
}
