    public Object splitWords(String txt) {
        boolean hasWhitespace = false;
        for (int i = 0; i < txt.length(); i++) {
            if (Character.isWhitespace(txt.charAt(i))) {
                hasWhitespace = true;
                break;
            }
        }

        if (hasWhitespace) {
            return Arrays.asList(txt.split("\\s+"));
