            int count = 0;
            for (int i = 0; i < txt.length(); i++) {
                char c = txt.charAt(i);
                if (Character.isLowerCase(c) && ((c - 'a') % 2 == 1)) {
                    count++;
                }
            }
            return count;
        }
    }
}
