import java.util.*;

class Solution {
    public boolean isSorted(List<Integer> lst) {
        if (lst == null) {
            return false;
        }
        if (lst.size() <= 1) {
            return true;
        }

        int count = 1;
        for (int i = 1; i < lst.size(); i++) {
            int prev = lst.get(i - 1);
            int curr = lst.get(i);

            if (curr < prev) {
                return false;
            }

            if (curr == prev) {
                count++;
                if (count > 2) {
                    return false;
                }
            } else {
                count = 1;
            }
        }

        return true;
    }
}
