import java.util.*;

class Solution {
    public String intersection(List<Integer> interval1, List<Integer> interval2) {
        long l = Math.max(interval1.get(0), interval2.get(0));
        long r = Math.min(interval1.get(1), interval2.get(1));

        if (l > r) {
            return "NO";
        }

        long length = r - l;

        return isPrime(length) ? "YES" : "NO";
    }

    private boolean isPrime(long n) {
        if (n < 2) {
            return false;
        }
        if (n == 2) {
            return true;
        }
        if (n % 2 == 0) {
            return false;
        }

        for (long i = 3; i <= n / i; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }
}
