        int length = r - l;

        if (length <= 1) {
            return "NO";
        }

        if (length == 2) {
            return "YES";
        }

        for (int i = 2; i < length; i++) {
            if (length % i == 0) {
                return "NO";
            }
        }

        return "YES";
    }
}

