import java.util.*;

class Solution {
    public List<Integer> minPath(List<List<Integer>> grid, int k) {
        int n = grid.size();
        int r = -1, c = -1;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid.get(i).get(j) == 1) {
                    r = i;
                    c = j;
                    break;
                }
            }
            if (r != -1) break;
        }
        List<Integer> ans = new ArrayList<>();
        Map<Integer, Integer> seen = new HashMap<>();
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};
        while (ans.size() < k) {
            int code = r * n + c;
            if (seen.containsKey(code)) {
                int cycleStart = seen.get(code);
                int cycleLen = ans.size() - cycleStart;
                int remaining = k - ans.size();
                for (int i = 0; i < remaining; i++) {
                    ans.add(ans.get(cycleStart + (i % cycleLen)));
                }
                break;
            }
            seen.put(code, ans.size());
            ans.add(grid.get(r).get(c));
            if (ans.size() == k) break;
            int bestVal = Integer.MAX_VALUE;
            int bestR = r, bestC = c;
            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d];
                int nc = c + dc[d];
                if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
                    int val = grid.get(nr).get(nc);
                    if (val < bestVal) {
                        bestVal = val;
                        bestR = nr;
                        bestC = nc;
                    }
                }
            }
            r = bestR;
            c = bestC;
        }
        return ans;
    }
}
