import java.util.*;

class Solution {
    public List<Integer> tri(int n) {
        if (n == 0) {
            return new ArrayList<>(Arrays.asList(1));
        }

        List<Integer> result = new ArrayList<>(Arrays.asList(1, 3));

        for (int i = 2; i <= n; i++) {
            if (i % 2 == 0) {
                result.add(i / 2 + 1);
            } else {
                int prev1 = result.get(result.size() - 1);
                int prev2 = result.get(result.size() - 2);
                result.add(prev1 + prev2 + (i + 3) / 2);
            }
        }

        return result;
    }
}
