class Solution {
    public List<Optional<Integer>> largestSmallestIntegers(List<Integer> lst) {
        Optional<Integer> largestNegative = Optional.empty();
        Optional<Integer> smallestPositive = Optional.empty();

        if (lst != null) {
            for (Integer n : lst) {
                if (n == null) {
                    continue;
                }

                if (n < 0) {
                    if (!largestNegative.isPresent() || n > largestNegative.get()) {
                        largestNegative = Optional.of(n);
                    }
                } else if (n > 0) {
                    if (!smallestPositive.isPresent() || n < smallestPositive.get()) {
                        smallestPositive = Optional.of(n);
                    }
                }
            }
        }

        return Arrays.asList(largestNegative, smallestPositive);
    }
}
