class Solution {
    public String fixSpaces(String text) {
        StringBuilder sb = new StringBuilder();
        int i = 0;

        while (i < text.length()) {
            if (text.charAt(i) == ' ') {
                int j = i;
                while (j < text.length() && text.charAt(j) == ' ') {
                    j++;
                }

                int count = j - i;
                if (count > 2) {
                    sb.append('-');
                } else {
                    sb.append("_".repeat(count));
                }

                i = j;
            } else {
                sb.append(text.charAt(i));
                i++;
            }
        }

        return sb.toString();
    }
}
