class Solution {
    public String filenameCheck(String file_name) {
        if (file_name == null) {
            return "No";
        }

        int firstDot = file_name.indexOf('.');
        int lastDot = file_name.lastIndexOf('.');

        if (firstDot == -1 || firstDot != lastDot) {
            return "No";
        }

        String name = file_name.substring(0, firstDot);
        String extension = file_name.substring(firstDot + 1);

        if (name.isEmpty()) {
            return "No";
        }

        char first = name.charAt(0);
        if (!((first >= 'a' && first <= 'z') || (first >= 'A' && first <= 'Z'))) {
            return "No";
        }

        if (!(extension.equals("txt") || extension.equals("exe") || extension.equals("dll"))) {
            return "No";
        }

        int digitCount = 0;
        for (int i = 0; i < file_name.length(); i++) {
            char c = file_name.charAt(i);
            if (c >= '0' && c <= '9') {
                digitCount++;
                if (digitCount > 3) {
                    return "No";
                }
            }
        }

        return "Yes";
    }
}
