import java.util.*;

class Solution {
    public List<Integer> minPath(List<List<Integer>> grid, int k) {
        int n = grid.size();
        int r = -1, c = -1;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid.get(i).get(j) == 1) {
                    r = i;
                    c = j;
                    break;
                }
            }
            if (r != -1) break;
        }

        List<Integer> ans = new ArrayList<>();
        ans.add(1);

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int step = 1; step < k; step++) {
            int minVal = Integer.MAX_VALUE;
            int nextR = -1, nextC = -1;

            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d];
                int nc = c + dc[d];

                if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
                    int val = grid.get(nr).get(nc);
                    if (val < minVal) {
                        minVal = val;
                        nextR = nr;
                        nextC = nc;
                    }
                }
            }

            ans.add(minVal);
            r = nextR;
            c = nextC;
        }

        return ans;
    }
}
