        if (firstDot == -1 || firstDot != lastDot) {
            return "No";
        }

        String beforeDot = file_name.substring(0, firstDot);
        String afterDot = file_name.substring(firstDot + 1);

        if (beforeDot.isEmpty()) {
            return "No";
        }

        char firstChar = beforeDot.charAt(0);
        if (!((firstChar >= 'a' && firstChar <= 'z') ||
              (firstChar >= 'A' && firstChar <= 'Z'))) {
            return "No";
        }

        if (!(afterDot.equals("txt") ||
              afterDot.equals("exe") ||
              afterDot.equals("dll"))) {
            return "No";
        }

        int digitCount = 0;
        for (int i = 0; i < file_name.length(); i++) {
            char c = file_name.charAt(i);
            if (c >= '0' && c <= '9') {
                digitCount++;
                if (digitCount > 3) {
                    return "No";
                }
            }
        }

        return "Yes";
