import java.util.*;

class Solution {
    public List<Integer> orderByPoints(List<Integer> nums) {
        List<Integer> result = new ArrayList<>(nums);
        result.sort((a, b) -> {
            int sumA = digitSum(a);
            int sumB = digitSum(b);
            return Integer.compare(sumA, sumB);
        });
        return result;
    }

    private int digitSum(int n) {
        String s = String.valueOf(n);
        int sum = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '-') continue;
            int digit = c - '0';
            if (i == 1 && n < 0) {
                sum -= digit;
            } else {
                sum += digit;
            }
        }
        return sum;
    }
}
