public class Solution {
    public int specialFilter(List<Integer> nums) {
        int count = 0;

        for (int num : nums) {
            if (num > 10) {
                int lastDigit = num % 10;
                int firstDigit = num;

                while (firstDigit >= 10) {
                    firstDigit /= 10;
                }

                if (firstDigit % 2 != 0 && lastDigit % 2 != 0) {
                    count++;
                }
            }
        }

        return count;
    }
