class Solution {
    public int getMaxTriples(int n) {
        long zeros = (n + 1) / 3; // count of i where i % 3 == 2
        long ones = n - zeros;

        long ans = zeros * (zeros - 1) * (zeros - 2) / 6
                 + ones * (ones - 1) * (ones - 2) / 6;

        return (int) ans;
    }
}
