        int index2 = planetNames.indexOf(planet2);

        if (index1 < index2) {
            return new ArrayList<>(planetNames.subList(index1 + 1, index2));
        } else {
            return new ArrayList<>(planetNames.subList(index2 + 1, index1));
        }
    }
}
