class Solution {
    public String StrongestExtension(String class_name, List<String> extensions) {
        String strongest = extensions.get(0);
        int strongestStrength = (int) (
            strongest.chars().filter(Character::isUpperCase).count()
            - strongest.chars().filter(Character::isLowerCase).count()
