import java.util.*;

class Solution {
    public boolean rightAngleTriangle(int a, int b, int c) {
        long[] sides = {a, b, c};
        Arrays.sort(sides);

        if (sides[0] <= 0) {
            return false;
        }

        if (sides[0] + sides[1] <= sides[2]) {
            return false;
        }

        return sides[0] * sides[0] + sides[1] * sides[1] == sides[2] * sides[2];
    }
}
